#include <stdio.h>
#include <stdlib.h>

/* Provided by the candidate in solution.c */
void merge_sorted(const int *a, int count_a,
                  const int *b, int count_b,
                  int *out);

static int read_int_array(int **out, int *count_out)
{
    int count;
    if (scanf("%d", &count) != 1 || count < 0) {
        return 0;
    }
    int *values = NULL;
    if (count > 0) {
        values = malloc((size_t)count * sizeof *values);
        if (values == NULL) {
            return 0;
        }
        for (int i = 0; i < count; i++) {
            if (scanf("%d", &values[i]) != 1) {
                free(values);
                return 0;
            }
        }
    }
    *out = values;
    *count_out = count;
    return 1;
}

int main(void)
{
    int *a = NULL, *b = NULL;
    int count_a = 0, count_b = 0;
    if (!read_int_array(&a, &count_a) || !read_int_array(&b, &count_b)) {
        free(a);
        return 1;
    }

    int total = count_a + count_b;
    int *out = NULL;
    if (total > 0) {
        out = malloc((size_t)total * sizeof *out);
        if (out == NULL) {
            free(a);
            free(b);
            return 1;
        }
    }

    merge_sorted(a, count_a, b, count_b, out);

    for (int i = 0; i < total; i++) {
        printf("%d%s", out[i], (i + 1 < total) ? " " : "");
    }
    printf("\n");

    free(a);
    free(b);
    free(out);
    return 0;
}

