"""Random pairs of sorted arrays to merge.

Both arrays are sorted before they are written out, which is the precondition
the one-pass merge depends on. The interesting shapes are about how the two
ranges sit relative to each other, so each builder places them differently.
"""


def generate(rng, count):
    builders = (_interleaved, _disjoint, _one_empty, _shared_values)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, a, b, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n%d\n%s\n" % (len(a), " ".join(str(v) for v in a),
                                         len(b), " ".join(str(v) for v in b)),
        "description": description,
    }


def _sorted_values(rng, low, high, how_many):
    return sorted(rng.randint(low, high) for _ in range(how_many))


def _interleaved(rng, index):
    return _case("overlapping ranges #%d" % index,
                 _sorted_values(rng, -50, 50, rng.randint(3, 7)),
                 _sorted_values(rng, -50, 50, rng.randint(3, 7)),
                 "The two arrays cover the same range, so the merge keeps "
                 "switching sides.")


def _disjoint(rng, index):
    low = _sorted_values(rng, -80, -20, rng.randint(2, 6))
    high = _sorted_values(rng, 20, 80, rng.randint(2, 6))
    first_low = rng.random() < 0.5
    return _case("one range entirely below the other #%d" % index,
                 low if first_low else high, high if first_low else low,
                 "One array is exhausted before the other is reached, so the "
                 "copy-the-remainder loop does most of the work.")


def _one_empty(rng, index):
    values = _sorted_values(rng, -40, 40, rng.randint(3, 8))
    empty_first = rng.random() < 0.5
    return _case("one side empty #%d" % index,
                 [] if empty_first else values, values if empty_first else [],
                 "An empty array's pointer may be NULL, so its count has to be "
                 "checked first.")


def _shared_values(rng, index):
    shared = sorted(rng.sample(range(-30, 30), rng.randint(2, 4)))
    a = sorted(shared + [rng.randint(-30, 30) for _ in range(rng.randint(1, 3))])
    b = sorted(shared + [rng.randint(-30, 30) for _ in range(rng.randint(1, 3))])
    return _case("values present in both #%d" % index, a, b,
                 "Several values appear on both sides. Equal elements are not "
                 "a special case, but they are where an off-by-one shows up.")
